WITH lines AS (SELECT id, currency, element FROM price_tiers LATERAL VIEW OUTER EXPLODE(discounts) e AS element) SELECT id, currency, RANK() OVER (ORDER BY element DESC NULLS FIRST) AS element_rank, STDDEV_SAMP(element) OVER (PARTITION BY currency) AS currency_stddev_samp_element, DENSE_RANK() OVER (PARTITION BY currency ORDER BY element DESC NULLS FIRST) AS element_dense_rank FROM lines
